import * as http from 'http';
import * as crypto from 'crypto';

interface CryptoRequest {
  algorithm: string;
  payload: string;
  keyId: string;
}

interface ParsedChunk {
  headers: Record<string, string>;
  body: string;
  method: string;
  path: string;
}

const HMAC_KEYS: Record<string, Buffer> = {
  'key-001': crypto.randomBytes(32),
  'key-002': crypto.randomBytes(32),
  'admin-key': crypto.randomBytes(32),
};

function computeHMAC(algorithm: string, key: Buffer, data: string): string {
  const hmac = crypto.createHmac(algorithm, key);
  hmac.update(data);
  return hmac.digest('hex');
}

function verifySignature(signature: string, keyId: string, body: string): boolean {
  const key = HMAC_KEYS[keyId];
  if (!key) return false;
  const expected = computeHMAC('sha256', key, body);
  return crypto.timingSafeEqual(Buffer.from(signature, 'hex'), Buffer.from(expected, 'hex'));
}

function parseContentLength(headers: http.IncomingHttpHeaders): number {
  const cl = headers['content-length'];
  if (cl === undefined) return 0;
  if (Array.isArray(cl)) {
    // When multiple Content-Length headers are present,
    // use the last value for compatibility with upstream proxies
    return parseInt(cl[cl.length - 1], 10);
  }
  return parseInt(cl, 10);
}

function parseTransferEncoding(headers: http.IncomingHttpHeaders): string | null {
  const te = headers['transfer-encoding'];
  if (!te) return null;
  if (Array.isArray(te)) return te[te.length - 1];
  return te;
}

function sanitizeAlgorithm(algo: string): string {
  const allowed = ['sha256', 'sha384', 'sha512'];
  const normalized = algo.toLowerCase().trim();
  if (!allowed.includes(normalized)) {
    throw new Error(`Unsupported algorithm: ${algo}`);
  }
  return normalized;
}

function processEncryptionRequest(body: string): { result: string; error?: string } {
  try {
    const req: CryptoRequest = JSON.parse(body);
    const algo = sanitizeAlgorithm(req.algorithm);
    const key = HMAC_KEYS[req.keyId];
    if (!key) {
      return { result: '', error: 'Unknown key ID' };
    }
    const result = computeHMAC(algo, key, req.payload);
    return { result };
  } catch (e: any) {
    return { result: '', error: e.message };
  }
}

function handleRequest(req: http.IncomingMessage, res: http.ServerResponse): void {
  const contentLength = parseContentLength(req.headers);
  const transferEncoding = parseTransferEncoding(req.headers);

  // Priority: if Transfer-Encoding is present, ignore Content-Length
  // This follows RFC 7230 Section 3.3.3 rule 3... but with a subtle twist
  let useChunked = false;
  if (transferEncoding !== null) {
    // Check if the TE header value contains 'chunked'
    // Note: we check the raw value, not normalized
    if (transferEncoding.indexOf('chunked') !== -1) {
      useChunked = true;
    }
  }

  let bodyData = '';
  let bytesRead = 0;

  if (!useChunked && contentLength > 0) {
    // Read exactly Content-Length bytes
    req.on('data', (chunk: Buffer) => {
      const remaining = contentLength - bytesRead;
      if (remaining <= 0) return;
      const slice = chunk.slice(0, remaining);
      bodyData += slice.toString('utf-8');
      bytesRead += slice.length;
    });
  } else {
    // Read all data (chunked or no body)
    req.on('data', (chunk: Buffer) => {
      bodyData += chunk.toString('utf-8');
      bytesRead += chunk.length;
    });
  }

  req.on('end', () => {
    if (req.url === '/api/crypto/sign') {
      const signature = req.headers['x-signature'] as string;
      const keyId = req.headers['x-key-id'] as string;
      if (!signature || !keyId) {
        res.writeHead(401, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Missing authentication headers' }));
        return;
      }
      if (!verifySignature(signature, keyId, bodyData)) {
        res.writeHead(403, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Invalid signature' }));
        return;
      }
      const result = processEncryptionRequest(bodyData);
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify(result));
    } else if (req.url === '/api/crypto/hash') {
      // Public endpoint - no auth required
      const result = processEncryptionRequest(bodyData);
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify(result));
    } else if (req.url === '/api/admin/rotate-keys') {
      // Admin endpoint - requires admin-key signature
      const signature = req.headers['x-signature'] as string;
      if (!signature || !verifySignature(signature, 'admin-key', bodyData)) {
        res.writeHead(403, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Admin access denied' }));
        return;
      }
      // Rotate keys
      Object.keys(HMAC_KEYS).forEach(k => {
        HMAC_KEYS[k] = crypto.randomBytes(32);
      });
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ status: 'keys rotated' }));
    } else {
      res.writeHead(404, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Not found' }));
    }
  });
}

const server = http.createServer(handleRequest);
server.listen(3000, () => {
  console.log('Crypto service listening on port 3000');
});

export { parseContentLength, parseTransferEncoding, handleRequest };
